import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Gmail API Search Queries","description":"","frontmatter":{"prev":{"text":"Fetch Single Mail (Gmail)","link":"/documentation/field-types/google-service-gmail/fetch-single-mail-gmail"},"next":{"text":"Send Mail (Gmail)","link":"/documentation/field-types/google-service-gmail/send-mail-gmail"}},"headers":[],"relativePath":"documentation/field-types/google-service-gmail/gmail-api-search-queries.md","filePath":"documentation/field-types/google-service-gmail/gmail-api-search-queries.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/google-service-gmail/gmail-api-search-queries.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="gmail-api-search-queries" tabindex="-1">Gmail API Search Queries <a class="header-anchor" href="#gmail-api-search-queries" aria-label="Permalink to “Gmail API Search Queries”">​</a></h1><p>Comprehensive reference guide to Gmail search operators and syntax for filtering messages in automated workflows.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>Gmail queries allow you to isolate exact messages based on sender, subject, date, read status, and attachment attributes. These query expressions are configured in the <strong>Search Query</strong> parameter of <a href="/documentation/field-types/google-service-gmail/fetch-mail-gmail.html">Fetch Mail (Gmail)</a> and <a href="/documentation/field-types/google-service-gmail/fetch-single-mail-gmail.html">Fetch Single Mail (Gmail)</a>.</p><hr><h2 id="common-examples" tabindex="-1">Common Gmail Query Operators <a class="header-anchor" href="#common-examples" aria-label="Permalink to “Common Gmail Query Operators”">​</a></h2><table tabindex="0"><thead><tr><th>Query</th><th>Function</th><th>Example</th></tr></thead><tbody><tr><td><code>is:unread</code></td><td>Matches only unread messages.</td><td><code>is:unread from:billing@service.com</code></td></tr><tr><td><code>is:read</code></td><td>Matches read messages.</td><td><code>is:read subject:statement</code></td></tr><tr><td><code>in:inbox</code></td><td>Scopes search to the Inbox.</td><td><code>in:inbox is:unread</code></td></tr><tr><td><code>in:sent</code></td><td>Scopes search to Sent mail.</td><td><code>in:sent to:client@company.com</code></td></tr><tr><td><code>in:trash</code></td><td>Searches deleted items in Trash.</td><td><code>in:trash</code></td></tr><tr><td><code>in:spam</code></td><td>Searches messages in Spam.</td><td><code>in:spam</code></td></tr><tr><td><code>has:attachment</code></td><td>Matches messages containing files.</td><td><code>has:attachment filename:pdf</code></td></tr><tr><td><code>larger:5m</code></td><td>Messages with total size over 5 megabytes.</td><td><code>larger:5m</code></td></tr><tr><td><code>smaller:1m</code></td><td>Messages with total size under 1 megabyte.</td><td><code>smaller:1m</code></td></tr></tbody></table><hr><h2 id="sender-receiver-filters" tabindex="-1">Sender &amp; Recipient Filters <a class="header-anchor" href="#sender-receiver-filters" aria-label="Permalink to “Sender &amp; Recipient Filters”">​</a></h2><table tabindex="0"><thead><tr><th>Operator</th><th>Syntax</th><th>Description</th></tr></thead><tbody><tr><td><code>from:</code></td><td><code>from:support@domain.com</code></td><td>Matches emails from a specific sender address or domain.</td></tr><tr><td><code>to:</code></td><td><code>to:user@domain.com</code></td><td>Matches emails sent directly to the specified recipient.</td></tr><tr><td><code>cc:</code></td><td><code>cc:manager@domain.com</code></td><td>Matches emails where the address is CC&#39;d.</td></tr><tr><td><code>bcc:</code></td><td><code>bcc:audit@domain.com</code></td><td>Matches emails where the address is BCC&#39;d.</td></tr></tbody></table><hr><h2 id="label-category-filters" tabindex="-1">Label &amp; Category Filters <a class="header-anchor" href="#label-category-filters" aria-label="Permalink to “Label &amp; Category Filters”">​</a></h2><table tabindex="0"><thead><tr><th>Operator</th><th>Target</th><th>Description</th></tr></thead><tbody><tr><td><code>label:</code></td><td><code>label:important</code>, <code>label:finance</code></td><td>Scopes query to a specific system or user label.</td></tr><tr><td><code>category:primary</code></td><td>Primary Inbox tab</td><td>Filters emails categorized as Primary by Gmail.</td></tr><tr><td><code>category:social</code></td><td>Social tab</td><td>Notifications from social networks.</td></tr><tr><td><code>category:promotions</code></td><td>Promotions tab</td><td>Marketing and commercial emails.</td></tr><tr><td><code>category:updates</code></td><td>Updates tab</td><td>Receipts, statements, and bills.</td></tr><tr><td><code>category:forums</code></td><td>Forums tab</td><td>Discussion boards and mailing lists.</td></tr></tbody></table><hr><h2 id="date-time-filters" tabindex="-1">Date &amp; Time Filters <a class="header-anchor" href="#date-time-filters" aria-label="Permalink to “Date &amp; Time Filters”">​</a></h2><table tabindex="0"><thead><tr><th>Operator</th><th>Format</th><th>Description</th></tr></thead><tbody><tr><td><code>newer_than:</code></td><td><code>newer_than:1d</code>, <code>newer_than:2h</code></td><td>Matches emails received within the last relative time window (<code>d</code> = days, <code>h</code> = hours, <code>m</code> = months).</td></tr><tr><td><code>older_than:</code></td><td><code>older_than:7d</code></td><td>Matches emails older than the specified relative duration.</td></tr><tr><td><code>after:</code></td><td><code>after:2025/01/01</code></td><td>Absolute date lower bound (YYYY/MM/DD).</td></tr><tr><td><code>before:</code></td><td><code>before:2025/12/31</code></td><td>Absolute date upper bound (YYYY/MM/DD).</td></tr></tbody></table><hr><h2 id="attachment-filters" tabindex="-1">Attachment Filters <a class="header-anchor" href="#attachment-filters" aria-label="Permalink to “Attachment Filters”">​</a></h2><table tabindex="0"><thead><tr><th>Operator</th><th>Syntax</th><th>Description</th></tr></thead><tbody><tr><td><code>has:attachment</code></td><td><code>has:attachment</code></td><td>Requires at least one attachment present.</td></tr><tr><td><code>filename:</code></td><td><code>filename:pdf</code>, <code>filename:invoice.pdf</code></td><td>Matches specific file extensions or file names.</td></tr></tbody></table><hr><h2 id="content-search" tabindex="-1">Content &amp; Keyword Matching <a class="header-anchor" href="#content-search" aria-label="Permalink to “Content &amp; Keyword Matching”">​</a></h2><table tabindex="0"><thead><tr><th>Operator</th><th>Syntax</th><th>Description</th></tr></thead><tbody><tr><td><code>subject:</code></td><td><code>subject:&quot;Verification Code&quot;</code></td><td>Matches exact subject line text when quoted.</td></tr><tr><td>Exact phrase</td><td><code>&quot;account created&quot;</code></td><td>Matches the exact phrase anywhere in subject or body.</td></tr><tr><td>Negation</td><td><code>-from:spam.com</code></td><td>Excludes matching messages using the <code>-</code> prefix.</td></tr></tbody></table><hr><h2 id="combining-queries" tabindex="-1">Combining Operators <a class="header-anchor" href="#combining-queries" aria-label="Permalink to “Combining Operators”">​</a></h2><p>Multiple operators can be chained with spaces (equivalent to logical <code>AND</code>) or grouped with <code>OR</code>:</p><h3 id="compound-and" tabindex="-1">Compound AND <a class="header-anchor" href="#compound-and" aria-label="Permalink to “Compound AND”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from:security@bank.com is:unread newer_than:1h</span></span></code></pre></div><p><em>Matches unread messages from <code>security@bank.com</code> received within the last hour.</em></p><h3 id="compound-or" tabindex="-1">Compound OR <a class="header-anchor" href="#compound-or" aria-label="Permalink to “Compound OR”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from:(auth@service.com OR noreply@service.com) subject:OTP</span></span></code></pre></div><p><em>Matches messages from either sender containing &quot;OTP&quot; in the subject.</em></p><hr><h2 id="automation-tips" tabindex="-1">Automation Best Practices <a class="header-anchor" href="#automation-tips" aria-label="Permalink to “Automation Best Practices”">​</a></h2><ol><li><strong>Always Use <code>newer_than</code> for OTPs</strong>: Add <code>newer_than:1h</code> or <code>newer_than:1d</code> to ensure past authentication emails are not returned.</li><li><strong>Combine <code>is:unread</code> with Read Flagging</strong>: Use <code>is:unread</code> alongside the <strong>Remove UNREAD Label</strong> setting in the field configuration to guarantee one-time processing.</li><li><strong>Quote Multi-Word Phrases</strong>: Wrap phrases in double quotes (<code>subject:&quot;Your Security Code&quot;</code>).</li></ol><hr><h2 id="related" tabindex="-1">Related Documentation <a class="header-anchor" href="#related" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/chat.svg" class="doc-icon"> <a href="/documentation/field-types/google-service-gmail/fetch-mail-gmail.html">Fetch Mail (Gmail)</a></li><li><img src="/svg/globe.svg" class="doc-icon"> <a href="/documentation/field-types/google-service-gmail/fetch-single-mail-gmail.html">Fetch Single Mail (Gmail)</a></li><li><img src="/svg/click.svg" class="doc-icon"> <a href="/documentation/field-types/google-service-gmail/send-mail-gmail.html">Send Mail (Gmail)</a></li></ul>`,38)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};